using System;
using System.IO;
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using IdleRestaurant;
public static class RestaurantValidation {
 [Serializable] class Golden {public double[] values;}
 [Serializable] class Result {public string name,status,detail;public Result(string n,string s,string d){name=n;status=s;detail=d;}}
 [Serializable] class Report {public string utc;public int passed,failed;public Result[] checks;}
 static List<Result> results;static void Check(string name,Action test){try{test();results.Add(new Result(name,"pass",""));}catch(Exception e){results.Add(new Result(name,"fail",e.Message));Debug.LogError(name+": "+e.Message);}}
 static void Require(bool condition,string message){if(!condition)throw new Exception(message);}
 [MenuItem("Restaurant/Production/Run Acceptance Checks")]
 public static void Run(){results=new List<Result>();var c=AssetDatabase.LoadAssetAtPath<RestaurantCatalog>(RestaurantProductionBuilder.CatalogPath);
  Check("Catalog shape",()=>Require(c.outlets.Length==40&&c.managers.Length==71&&c.research.Length==17,"Wrong content count"));
  Check("21600 reference cost fixtures",()=>{var golden=Newtonsoft.Json.JsonConvert.DeserializeObject<Golden>(File.ReadAllText("Design/CostGolden.json"));int k=0;bool previous=c.useNewCosts;try{foreach(bool variant in new[]{false,true}){c.useNewCosts=variant;for(int i=0;i<40;i++)for(int card=0;card<9;card++)for(int level=0;level<30;level++){double actual=Economy.Cost(c,c.outlets[i],card,level,0);Require(actual==golden.values[k],"Cost mismatch at "+i+"/"+card+"/"+level+"/"+variant+": "+actual+" != "+golden.values[k]);k++;}}}finally{c.useNewCosts=previous;}Require(k==21600,"Fixture count");});
  Check("279 exact upgrade effects",()=>{var fixture=Newtonsoft.Json.JsonConvert.DeserializeObject<Golden>(File.ReadAllText("Design/EffectGolden.json"));int n=0;for(int card=0;card<9;card++)for(int level=0;level<=30;level++)Require(Economy.Effect(card,level)==fixture.values[n++],"Effect differs at "+card+"/"+level);});
  Check("Research discounts apply by stage",()=>{var game=new RestaurantGame(c);int i=Array.FindIndex(c.research,x=>x.key=="bds");game.State.research[i].level=100;Require(Math.Abs(game.Discount(0)-1)<1e-12&&Math.Abs(game.Discount(3)-.55)<1e-12&&Math.Abs(game.Discount(6)-1)<1e-12,"Stage discount leaked");});
  Check("Service gem cap and delayed settlement",()=>{var game=new RestaurantGame(c);game.Now=()=>86400;var state=game.State.outlets[0];state.ordered=state.cooked=state.seated=c.outlets[0].capacity;state.waveIncome=100;game.State.waveGemDay=1;game.State.waveGemsEarned=99;game.Tick(.05);Require(game.State.gems==0&&state.pendingWaveGems==1&&state.pendingBonus==10,"Reward granted before delay");for(int i=0;i<101;i++)game.Tick(.05);Require(game.State.gems==1&&state.pendingBonus==0,"Reward did not settle once");});
  Check("Cumulative manager duplicates",()=>{var game=new RestaurantGame(c);game.State.managerCopies[0]=4;game.State.managerLevels[0]=1;Require(game.LevelManager(0)&&game.LevelManager(0),"Threshold upgrade failed");Require(game.State.managerCopies[0]==4&&game.State.managerLevels[0]==3&&!game.LevelManager(0),"Duplicate count consumed or incorrect threshold");});
  Check("Star research timing and district effect",()=>{var game=new RestaurantGame(c);double now=1000;game.Now=()=>now;game.State.prestigeCoins=1;double before=game.Pay(0,0,0);Require(game.BuyPrestige(0),"Star research failed");Require(game.State.prestige[0]==0&&game.State.prestigeCoins==0,"Research completed immediately");now=game.State.prestigeFinish[0]+1;game.Tick(.05);Require(game.State.prestige[0]==1&&Math.Abs(game.Pay(0,0,0)/before-1.05)<1e-12,"District research effect incorrect");});
  Check("Starter replacement and cap",()=>{var g=new RestaurantGame(c);Require(g.Cost(0,0)==(c.useNewCosts?25:50),"Starter multiplied twice");g.State.cash=1e9;for(int i=0;i<30;i++)Require(g.Buy(0),"Could not buy level "+i);Require(!g.Buy(0)&&g.State.outlets[0].upgrades[0]==30,"Cap failed");});
  Check("Purchases reject insufficient funds",()=>{var g=new RestaurantGame(c);g.State.cash=0;Require(!g.Buy(0)&&g.State.outlets[0].upgrades[0]==0,"Unaffordable purchase granted");});
  Check("Wave conservation and payout at base and max levels",()=>{foreach(int level in new[]{0,30})for(int outlet=0;outlet<40;outlet++){var g=new RestaurantGame(c);g.Now=()=>1000;g.State.selected=outlet;for(int i=0;i<40;i++)g.State.outlets[i].open=i==outlet;var s=g.State.outlets[outlet];for(int j=0;j<9;j++)s.upgrades[j]=level;double expected=0;for(int guest=0;guest<c.outlets[outlet].capacity;guest++)for(int stage=0;stage<3;stage++)expected+=g.Pay(outlet,guest,stage);expected*=1+c.completionFraction;double before=g.State.cash;int ticks=0;while((s.waves==0||s.clearClock>0)&&ticks++<100000)g.Tick(.05);Require(s.waves==1,"Wave did not finish at "+outlet);Require(Math.Abs((g.State.cash-before)-expected)<=Math.Max(.000001,expected*1e-10),"Incorrect stage/bonus payout at "+outlet);Require(s.ordered==0&&s.cooked==0&&s.seated==0,"Counts not reset");}});
  Check("Save round-trip and corrupt-primary recovery",()=>{string p=Path.Combine(Path.GetTempPath(),"restaurant-acceptance-save.json");foreach(string f in new[]{p,p+".bak",p+".tmp"})if(File.Exists(f))File.Delete(f);var store=new SaveStore(p);var g=new RestaurantGame(c);g.State.cash=1234;store.Write(g.State);g.State.cash=5678;store.Write(g.State);Require(store.Read(out _).cash==5678,"Round trip failed");File.WriteAllText(p,"damaged");var recovered=store.Read(out bool backup);Require(backup&&recovered.cash==1234,"Backup recovery failed");foreach(string f in new[]{p,p+".bak",p+".tmp"})if(File.Exists(f))File.Delete(f);});
  Check("Both damaged saves preserved before new progress",()=>{string folder=Path.Combine(Path.GetTempPath(),"restaurant-corruption-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string path=Path.Combine(folder,"save.json");File.WriteAllText(path,"bad primary");File.WriteAllText(path+".bak","bad backup");var store=new SaveStore(path);Require(store.Read(out _)==null&&store.HadUnreadableSave,"Damage not reported");Require(Directory.GetFiles(folder,"*.unreadable-*").Length==2,"Original damaged files not preserved");store.Write(new RestaurantGame(c).State);Require(store.Read(out _)!=null,"New progress could not be saved");Directory.Delete(folder,true);});
  Check("Offline standard cap and one-time claim",()=>{var g=new RestaurantGame(c);g.Now=()=>100000;g.State.utc=1;double expected=g.NetworkIncome()/60*c.offlineCapSeconds*c.offlineFraction;g.Resume(100000);Require(Math.Abs(g.State.pendingOffline-expected)<1e-8,"Offline cap failed");double before=g.State.cash;g.ClaimOffline();g.ClaimOffline();Require(Math.Abs(g.State.cash-before-expected)<1e-8,"Double offline grant");});
  Check("Receipt grant idempotence",()=>{var g=new RestaurantGame(c);g.ApplyReceipt("sandbox-test",()=>g.State.gems+=100);g.ApplyReceipt("sandbox-test",()=>g.State.gems+=100);Require(g.State.gems==100,"Duplicate receipt granted twice");});
  Check("Research timer and slot limits",()=>{var g=new RestaurantGame(c);g.Now=()=>1000;g.State.cash=1e30;Require(g.StartResearch(0),"Research failed");Require(!g.StartResearch(1),"Slot limit failed");double finish=g.State.research[0].finish;g.Now=()=>finish+1;g.Tick(.05);Require(g.State.research[0].level==1&&g.State.research[0].finish==0,"Completion failed");});
  Check("Unlock dependency and cash",()=>{var g=new RestaurantGame(c);g.State.cash=1e30;Require(g.Open(2),"Cash-funded route unexpectedly blocked");Require(g.Open(1),"Second outlet blocked");Require(!g.CanOpen(8,out _),"Licence bypass");});
  Check("Prestige local reset, wallet retention and safe state",()=>{var g=new RestaurantGame(c);var s=g.State.outlets[0];for(int i=0;i<9;i++)s.upgrades[i]=30;s.clearClock=5;Require(!g.Prestige(),"Unsafe prestige allowed");s.clearClock=0;double cash=g.State.cash;Require(g.Prestige(),"Prestige denied");Require(s.rank==1&&g.State.prestigeCoins==1&&g.State.cash==cash&&s.upgrades[0]==0,"Incorrect reset");});
  var report=new Report{utc=DateTime.UtcNow.ToString("o"),checks=results.ToArray()};foreach(var r in results)if(r.status=="pass")report.passed++;else report.failed++;Directory.CreateDirectory("Verification");File.WriteAllText("Verification/CoreChecks.json",JsonUtility.ToJson(report,true));Debug.Log("RESTAURANT_ACCEPTANCE passed="+report.passed+" failed="+report.failed);
 }
}
